import { useCallback, useEffect, useRef, useState } from "react";

export type Language = "python" | "javascript" | "typescript";

type Runtime = "python" | "javascript";
type RunResult = { output: string; durationMs: number };
type WorkerResult = RunResult & { id: number; error?: string };
type PendingRun = {
  id: number;
  resolve: (result: RunResult) => void;
  reject: (error: Error) => void;
};

export class RuntimeResetError extends Error {}

function getRuntime(language: Language): Runtime {
  return language === "python" ? "python" : "javascript";
}

function createWorker(runtime: Runtime) {
  if (runtime === "python") {
    return new Worker(
      new URL("./python-runtime.worker.ts", import.meta.url),
      {
        type: "module",
      },
    );
  }

  return new Worker(
    new URL("./javascript-runtime.worker.ts", import.meta.url),
    { type: "module" },
  );
}

export function useCodeRuntime() {
  const workerRef = useRef<Worker | null>(null);
  const runtimeRef = useRef<Runtime | null>(null);
  const pendingRef = useRef<PendingRun | null>(null);
  const nextId = useRef(1);
  const [language, setLanguage] = useState<Language | null>(null);
  const [status, setStatus] = useState<
    "idle" | "loading" | "running" | "ready"
  >("idle");

  const stop = useCallback(() => {
    workerRef.current?.terminate();
    workerRef.current = null;
    runtimeRef.current = null;
    pendingRef.current?.reject(new RuntimeResetError("Runtime reset"));
    pendingRef.current = null;
    setLanguage(null);
    setStatus("idle");
  }, []);

  const run = useCallback((code: string, nextLanguage: Language) => {
    const nextRuntime = getRuntime(nextLanguage);
    const isStarting = runtimeRef.current !== nextRuntime;

    if (isStarting) {
      workerRef.current?.terminate();
      workerRef.current = createWorker(nextRuntime);
      runtimeRef.current = nextRuntime;
    }

    const worker = workerRef.current!;
    setLanguage(nextLanguage);
    setStatus(isStarting ? "loading" : "running");

    return new Promise<RunResult>((resolve, reject) => {
      const id = nextId.current++;
      pendingRef.current = { id, resolve, reject };
      worker.onmessage = (event: MessageEvent<WorkerResult>) => {
        if (event.data.id !== pendingRef.current?.id) return;
        pendingRef.current = null;
        setStatus("ready");
        if (event.data.error) reject(new Error(event.data.error));
        else resolve(event.data);
      };
      worker.onerror = () => {
        workerRef.current = null;
        runtimeRef.current = null;
        pendingRef.current = null;
        setLanguage(null);
        setStatus("idle");
        reject(new Error("The code runtime could not be loaded."));
      };
      worker.postMessage({ id, code, language: nextLanguage });
    });
  }, []);

  useEffect(() => () => stop(), [stop]);

  return { language, run, reset: stop, status };
}

import { loadPyodide, version } from "pyodide";

const runtime = loadPyodide({
  indexURL: `https://cdn.jsdelivr.net/pyodide/v${version}/full/`,
});

self.onmessage = async (event: MessageEvent<{ id: number; code: string }>) => {
  const startedAt = performance.now();
  const output: string[] = [];

  try {
    const pyodide = await runtime;
    await pyodide.loadPackagesFromImports(event.data.code);
    pyodide.setStdout({ batched: (text) => output.push(text) });
    pyodide.setStderr({ batched: (text) => output.push(text) });

    const value = await pyodide.runPythonAsync(event.data.code);
    if (value != null) output.push(value.toString());
    value?.destroy?.();

    self.postMessage({
      id: event.data.id,
      output: output.join("\n"),
      durationMs: Math.round(performance.now() - startedAt),
    });
  } catch (error) {
    self.postMessage({
      id: event.data.id,
      error: error instanceof Error ? error.message : String(error),
      durationMs: Math.round(performance.now() - startedAt),
    });
  }
};

type Language = "javascript" | "typescript";

type RunRequest = {
  id: number;
  code: string;
  language: Language;
};

function formatValue(value: unknown) {
  if (typeof value === "string") return value;
  if (typeof value === "undefined") return "undefined";
  if (typeof value === "function") return value.toString();

  try {
    return JSON.stringify(value) ?? String(value);
  } catch {
    return String(value);
  }
}

self.onmessage = async (event: MessageEvent<RunRequest>) => {
  const startedAt = performance.now();
  const output: string[] = [];
  const write = (...values: unknown[]) => {
    output.push(values.map(formatValue).join(" "));
  };

  try {
    let source = event.data.code;

    if (event.data.language === "typescript") {
      const ts = await import("typescript");
      const result = ts.transpileModule(source, {
        compilerOptions: {
          module: ts.ModuleKind.None,
          target: ts.ScriptTarget.ES2022,
        },
        reportDiagnostics: true,
      });
      const errors = result.diagnostics?.filter(
        (diagnostic) => diagnostic.category === ts.DiagnosticCategory.Error,
      );

      if (errors?.length) {
        throw new Error(
          errors
            .map((diagnostic) =>
              ts.flattenDiagnosticMessageText(diagnostic.messageText, "\n"),
            )
            .join("\n"),
        );
      }

      source = result.outputText;
    }

    const AsyncFunction = Object.getPrototypeOf(async () => undefined)
      .constructor as new (
      ...args: string[]
    ) => (...values: unknown[]) => Promise<unknown>;
    const execute = new AsyncFunction("console", `"use strict";\n${source}`);
    const value = await execute({
      debug: write,
      error: write,
      info: write,
      log: write,
      table: write,
      warn: write,
    });

    if (value !== undefined) output.push(formatValue(value));

    self.postMessage({
      id: event.data.id,
      output: output.join("\n"),
      durationMs: Math.round(performance.now() - startedAt),
    });
  } catch (error) {
    self.postMessage({
      id: event.data.id,
      error: error instanceof Error ? error.message : String(error),
      durationMs: Math.round(performance.now() - startedAt),
    });
  }
};
